import React from 'react'
import { withRouter } from 'react-router-dom'
import ImageUploader from 'react-images-upload'
import Header from '../Header';
import Sidebar from '../Sidebar';
import Select from 'react-select'

class MemberEdit extends React.Component {

    constructor(props){
        super(props)
        this.state = {
            id: '',
            // name: '',
            // phone: '',
            // email: '',
            // city: '',
            // address: '',
            // company: '',
            // newMember: '',
            // errorName: '',
            // errorCity: '',
            // errorCompany: '',
            // errorPhone: '',
            // errorEmail: '',
            // biography: '',
            memberDetails: [],
            //added
            name: '',
            surname: '',
            sex: '',                 // ostavljeno kao što je bilo
            speciality: '',
            dateOfBirth: '',
            company: '',
            city: '',
            expire: '',
            faximil: '',            
            email: '',
            phone: '',
            //end
        }
    }

    componentDidMount() {
        this.setup()
    }

    setup = () => {
        this.props.getMemberDetails(parseInt(this.props.member.id))
        this.resetErrors()
    }

    static getDerivedStateFromProps(nextProps, prevProps) {

            let _id, _name, _surname, _sex, _speciality, _dateOfBirth, _company, _city, _expire, _faximil, _email, _phone, _memberDetails = []
            if(nextProps.memberDetails !== prevProps.memberDetails) {
                _memberDetails = nextProps.memberDetails
                _id =  nextProps.memberDetails.id
                _name =  nextProps.memberDetails.name
                _surname =  nextProps.memberDetails.surname
                _sex =  nextProps.memberDetails.sex
                _speciality =  nextProps.memberDetails.speciality
                _dateOfBirth =  nextProps.memberDetails.date_of_birth
                _company =  nextProps.memberDetails.company
                _city =  nextProps.memberDetails.city
                _expire =  nextProps.memberDetails.expire
                _faximil =  nextProps.memberDetails.fax_nbr
                _email =  nextProps.memberDetails.email
                _phone =  nextProps.memberDetails.phone

                // --- JEDINA PROMJENA: mapiramo string u react-select option objekat ---
                const _sexOption =
                    _sex === 'ženski'
                      ? { value: 2, label: 'ženski' }
                      : _sex === 'muški'
                      ? { value: 1, label: 'muški' }
                      : null;
                // ---------------------------------------------------------------------

                return {
                    // id: _id,
                    // name: _name,
                    // email: _email,
                    // phone: _phone,
                    // city: {
                    //     value: _city !== undefined ? _city.id : "",
                    //     label: _city !== undefined ? _city.name : ""
                    // },
                    // address: _address,
                    // company: _company,
                    // biography: _biography,
                    // memberDetails: _memberDetails
                    id: _id,
                    name: _name,
                    surname: _surname,
                    sex: _sexOption,   // <-- ovdje koristimo option objekat za Select
                    speciality: _speciality,
                    dateOfBirth: _dateOfBirth,
                    company: _company,
                    city: {
                        value: _city !== undefined ? _city.id : "",
                        label: _city !== undefined ? _city.name : ""
                    },
                    expire: _expire,
                    faximil: _faximil,
                    email: _email,
                    phone: _phone,
                    memberDetails: _memberDetails
                }
            }
           return null

        }
        
    changeName = (input) => {
        this.setState({
            name: input.target.value
        })
    }

    changeAddress = (input) => {
        this.setState({
            address: input.target.value
        })
    }

    changePhone = (input) => {
        this.setState({
            phone: input.target.value
        })
    }

    changeCity = (input) => {
        this.setState({
            city: input
        })
    }

    changeAddress = (input) => {
        this.setState({
            address: input.target.value
        })
    }

    changeCompany = (input) => {
        this.setState({
            company: input.target.value
        })
    }

    changeBiography = (input) => {
        this.setState({
            biography: input.target.value
        })
    }

    changeEmail = (input) => {
        this.setState({
            email: input.target.value
        })
    }
    
    changeSurname = (input) => {   
        this.setState({
            surname: input.target.value
        })
    }

    changeSex = (input) => {
        this.setState({
            sex: input
        })
    }

    resetErrors = () => {
        this.setState({
            errorName: '',
            errorCompany: '',
            errorCity: '',
            errorPhone: '',
            errorEmail: ''
        })
    }
        changedateOfBirth = (input) => {   
        this.setState({
            dateOfBirth: input.target.value
        })
    }
        changeSpeciality = (input) => {   
        this.setState({
            speciality: input.target.value
        })
    }
    changeExpire = (input) => {
        this.setState({
            expire: input.target.value
        })
    }
        changeFaximil = (input) => {
        this.setState({
            faximil: input.target.value
        })
    }

    handleValidation = () => {
        // (ostavljeno netaknuto)
    }

    submitForm = (e) => {
        e.preventDefault()
        // ako backend očekuje string "muški"/"ženski", šaljemo labelu;
        // (OSTALO NIŠTA NIJE DIRANO)
        let member = {
            id: this.state.id,
            name: this.state.name,
            surname: this.state.surname,
            sex: this.state.sex && this.state.sex.label ? this.state.sex.label : this.state.sex, // <-- JEDINA PROMJENA ZA SLANJE
            speciality: this.state.speciality,
            dateOfBirth: this.state.dateOfBirth,
            company: this.state.company,
            city_id: this.state.city !== undefined ? this.state.city.value : "",
            expire: this.state.expire,
            fax_nbr: this.state.faximil,
            email: this.state.email,
            phone: this.state.phone,
        }

        this.props.editMember(member)
        alert("Uspješno ste promjenili podatke o članu komore")
    }

    render() {

        const sex = [
            {
            "value": 1,
            "label": 'muški'
            },
            {
            "value": 2,
            "label": 'ženski'
            },
        ]
        const options = [
            {
                "value": 1,
                "label": "Andrijevica"
            },
            {
                "value": 2,
                "label": "Bar"
            },
            {
                "value": 3,
                "label": "Berane"
            },
            {
                "value": 4,
                "label": "Bijelo Polje"
            },
            {
                "value": 5,
                "label": "Budva"
            },
            {
                "value": 6,
                "label": "Cetinje"
            },
            {
                "value": 7,
                "label": "Danilovgrad"
            },
            {
                "value": 8,
                "label": "Gusinje"
            },
            {
                "value": 9,
                "label": "Herceg Novi"
            },
            {
                "value": 10,
                "label": "Kolašin"
            },
            {
                "value": 11,
                "label": "Kotor"
            },
            {
                "value": 12,
                "label": "Mojkovac"
            },
            {
                "value": 13,
                "label": "Nikšić"
            },
            {
                "value": 14,
                "label": "Petnjica"
            },
            {
                "value": 15,
                "label": "Plav"
            },
            {
                "value": 16,
                "label": "Plužine"
            },
            {
                "value": 17,
                "label": "Pljevlja"
            },
            {
                "value": 18,
                "label": "Podgorica"
            },
            {
                "value": 19,
                "label": "Rožaje"
            },
            {
                "value": 20,
                "label": "Šavnik"
            },
            {
                "value": 21,
                "label": "Tivat"
            },
            {
                "value": 22,
                "label": "Tuzi"
            },
            {
                "value": 23,
                "label": "Ulcinj"
            },
            {
                "value": 24,
                "label": "Zeta"
            },
            {
                "value": 25,
                "label": "Žabljak"
            }
        ]


        return(
            <div>
                <Header />
                <div className="col-md-2">
                    <Sidebar />
                </div>

                <div className="col-md-10 mainContent">
                {/* addMemberMargin */}
                    <div className="row box">
                        <form name="editForm" onSubmit={this.submitForm}> 
                            <div className="col-md-6 col-md-offset-3">
                                <div className="">
                                    <div className="box-header with-border">
                                        <h3 className="box-title">Izmijeni člana komore</h3>
                                    </div>
                                    <div className="box-body">
                                        <div className="form-group">
                                            <label>Ime </label>
                                            <input type="text" className="form-control" 
                                                placeholder="Unesite ime" 
                                                value={this.state.name || ""} 
                                                onChange={this.changeName} 
                                                required/>
                                        </div>
                                        <div className="form-group">
                                            <label>Prezime </label>
                                            <input type="text" className="form-control" 
                                                placeholder="Unesite prezime" 
                                                value={this.state.surname || ""} 
                                                onChange={this.changeSurname} 
                                                required/>
                                        </div>
                                        <div className="form-group">
                                            <label >Rod</label>
                                            <Select options={sex} placeholder="Izaberite rod" 
                                                onChange={this.changeSex}
                                                value={this.state.sex}
                                                />
                                        </div>
                                        <div className="form-group">
                                                <label>Datum rodjenja</label>
                                                <input type="text" className="form-control" 
                                                     placeholder="Npr: 11.11.2011 (u ovom formatu)"
                                                    value={this.state.dateOfBirth || ""} 
                                                    onChange={this.changedateOfBirth} 
                                                    required/>
                                            </div>
                                            <div className="form-group">
                                                <label>Specijalnost</label>
                                                <input type="text" className="form-control" 
                                                     placeholder="Specijalnost"
                                                    value={this.state.speciality || ""} 
                                                    onChange={this.changeSpeciality} 
                                                    required/>
                                            </div>
                                            <div className="form-group">
                                                <label >Grad</label>
                                                <Select options={options} placeholder="Izaberite grad" 
                                                    onChange={this.changeCity}
                                                    value={this.state.city}
                                                    />
                                            </div>
                                            <div className="form-group">
                                                <label >Isticanja</label>
                                                 <input type="text" className="form-control" 
                                                     placeholder="Isticanja"
                                                    value={this.state.expire || ""} 
                                                    onChange={this.changeExpire} 
                                                    required/>
                                            </div>
                                            <div className="form-group">
                                                <label >Br. faksimila</label>
                                                <input type="text" className="form-control" 
                                                     placeholder="Unesite broj faksimila"
                                                    value={this.state.faximil || ""} 
                                                    onChange={this.changeFaximil} 
                                                    required/>
                                            </div>
                                        <div className="form-group">
                                            <label >E-mail</label>
                                            <input type="text" className="form-control" 
                                                placeholder="Unesite email" 
                                                value={this.state.email || ""} 
                                                onChange={this.changeEmail} required />
                                            {/* <span style={{'color':'red'}}>{this.state.errorEmail}</span> */}
                                        </div>
                                        <div className="form-group">
                                            <label >Telefon</label>
                                            <input type="text" className="form-control" 
                                                placeholder="Unesite broj telefona" 
                                                value={this.state.phone || ""} 
                                                onChange={this.changePhone} required/>
                                        </div>


                                    </div>

                                    <div className="box-footer">
                                        <button type="submit" className="btn btn-primary">Izmijeni</button>
                                    </div>
                                </div>
                            </div>
                        </form>

                    </div>
                </div>
            </div>
        )
    }
}

export default withRouter(MemberEdit)
